-- job_postings.sql -- FICTIONAL job adverts for the sparqlite tutorial.
-- Generated by tutorial/make_tutorial_data.py; edit the script, not this file.
-- Every company, posting and salary here is MADE UP; any resemblance to a real
-- company is coincidental. Cities are real; salaries are annual, in US dollars.
-- language_iri matches the language IRIs in languages.ttl, except 'ABAP', which
-- is deliberately missing from the graph (try a LEFT JOIN).
-- Safe to run more than once: it drops and recreates the table.
DROP TABLE IF EXISTS job_postings;
CREATE TABLE job_postings(
  id           INTEGER PRIMARY KEY,
  title        TEXT NOT NULL,
  company      TEXT NOT NULL,
  language     TEXT NOT NULL,   -- display name, e.g. 'C#'
  language_iri TEXT NOT NULL,   -- e.g. 'http://example.org/pl/CSharp'
  city         TEXT NOT NULL,
  country      TEXT NOT NULL,   -- ISO 3166-1 alpha-2
  remote       INTEGER NOT NULL CHECK (remote IN (0, 1)),
  salary_usd   INTEGER NOT NULL,
  posted       TEXT NOT NULL    -- ISO 8601 date
);
CREATE INDEX job_postings_language_iri ON job_postings(language_iri);
